const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Define location and area of interest (4 km radius)
    const centerPoint = ee.Geometry.Point([49.357405, 39.014501]);
    const aoi = centerPoint.buffer(4000); // 4 km radius

    // Date ranges (±3 days window for each date)
    const date1Start = '2022-11-16';
    const date1End = '2022-11-22';
    const date2Start = '2023-02-10';
    const date2End = '2023-02-16';

    // Cloud masking function for Sentinel-2
    function maskS2clouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
          .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    // Function to calculate water mask (NDWI < 0 = land, NDWI > 0 = water)
    function addWaterMask(image) {
      const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
      const land = ndwi.lt(0).rename('land'); // Land where NDWI < 0
      return image.addBands([ndwi, land]);
    }

    // Get Sentinel-2 data for Nov 2022
    let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(date1Start, date1End)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(maskS2clouds)
      .map(addWaterMask);

    const size1 = col1.size().getInfo();
    console.log(`Nov 2022 images found: ${size1}`);

    if (size1 === 0) {
      console.log('No images for Nov 2022');
      console.log('<answer>C1</answer>');
      return;
    }

    // Get Sentinel-2 data for Feb 2023
    let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(date2Start, date2End)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
      .map(maskS2clouds)
      .map(addWaterMask);

    const size2 = col2.size().getInfo();
    console.log(`Feb 2023 images found: ${size2}`);

    if (size2 === 0) {
      console.log('No images for Feb 2023');
      console.log('<answer>C1</answer>');
      return;
    }

    // Create composites for each period
    const img1 = col1.median();
    const img2 = col2.median();

    // Count valid pixels for Nov 2022
    const count1 = img1.select('land').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    }).get('land').getInfo();

    console.log(`Nov 2022 valid pixels: ${count1}`);

    if (count1 === 0) {
      console.log('No valid pixels for Nov 2022 after masking');
      console.log('<answer>C2</answer>');
      return;
    }

    // Count valid pixels for Feb 2023
    const count2 = img2.select('land').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    }).get('land').getInfo();

    console.log(`Feb 2023 valid pixels: ${count2}`);

    if (count2 === 0) {
      console.log('No valid pixels for Feb 2023 after masking');
      console.log('<answer>C2</answer>');
      return;
    }

    // Calculate land area for each period
    const landStats1 = img1.select('land').reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    });

    const landStats2 = img2.select('land').reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    });

    const landPixels1 = landStats1.get('land').getInfo();
    const landPixels2 = landStats2.get('land').getInfo();

    console.log(`Nov 2022 land pixels: ${landPixels1}`);
    console.log(`Feb 2023 land pixels: ${landPixels2}`);

    if (landPixels1 === null || landPixels2 === null) {
      console.log('Calculation failed - null values');
      console.log('<answer>C3</answer>');
      return;
    }

    // Check if significant new land appeared (threshold: >100 pixels = ~0.1 km²)
    const landIncrease = landPixels2 - landPixels1;
    console.log(`Land pixel increase: ${landIncrease}`);

    // An island "appeared" if there's a significant increase in land area
    if (landIncrease > 100) {
      console.log('Island detected - significant land increase');
      console.log('<answer>A</answer>');
    } else {
      console.log('No significant island appearance detected');
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
